select public.send_student_plan('28000400-0000-4000-8000-000000000002',2);
select set_config('request.jwt.claim.sub','28000400-0000-4000-8000-000000000002',true);
select pg_temp.assert_true(exists(select 1 from public.professional_plan_update_day_views d join public.program_versions old on old.id=d.seen_version_id join public.program_assignments a on a.student_user_id=d.student_user_id and a.program_id=d.program_id join public.program_versions next on next.id=a.version_id where d.student_user_id=auth.uid() and d.day_key='monday' and next.version_number=2 and coalesce(next.weekly_plan->d.day_key,'[]'::jsonb) is not distinct from coalesce(old.weekly_plan->d.day_key,'[]'::jsonb) and coalesce(next.workout_titles->d.day_key,'null'::jsonb) is not distinct from coalesce(old.workout_titles->d.day_key,'null'::jsonb)),'carry predicate matches the unchanged monday');
select pg_temp.assert_true((select v.version_number=2 from public.professional_plan_update_day_views d join public.program_versions v on v.id=d.seen_version_id where d.student_user_id='28000400-0000-4000-8000-000000000002' and d.day_key='monday'),'unchanged monday carries to version two');
